insert into public.catalog_feats (id,feat_type,level,name_pt,description_pt,prerequisites,traits,source_book,source_page,ruleset,system_id,data) values
('dnd35.feat.acrobatico','comum',1,'Acrobático','+2 de bônus nos testes de Saltar e Acrobacia',null,ARRAY[]::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"acrobatico","name":"Acrobático","section":"comum","prerequisites":"—","summary":"+2 de bônus nos testes de Saltar e Acrobacia","notes":[]}'::jsonb),
('dnd35.feat.acuidade-com-arma','comum',1,'Acuidade com Arma','Quando estiver usando uma arma leve, sabre, chicote ou corrente com cravos apropriados para uma criatura do seu tamanho, pode usar o modificador de Destreza no lugar do modificador de Força nas jogadas de ataque corporal. A penalidade de armadura do escudo (se houver) também se aplica nesta situação.','Usar a arma, bônus base de ataque +1',ARRAY['nota-1','nota-2']::text[],'D&D 3.5 — Livro do Jogador',89,'v35','dnd35','{"id":"acuidade-com-arma","name":"Acuidade com Arma","section":"comum","prerequisites":"Usar a arma, bônus base de ataque +1","summary":"Aplica o modificador de Des (em vez de For) para ataques corporais com armas leves","notes":[1,2],"full":{"id":"acuidade-com-arma","name":"Acuidade com Arma","type":"geral","sourceBook":"D&D 3.5 — Livro do Jogador","sourcePage":89,"prerequisites":["Bônus de ataque +1"],"benefit":"Quando estiver usando uma arma leve, sabre, chicote ou corrente com cravos apropriados para uma criatura do seu tamanho, pode usar o modificador de Destreza no lugar do modificador de Força nas jogadas de ataque corporal. A penalidade de armadura do escudo (se houver) também se aplica nesta situação."}}'::jsonb),
('dnd35.feat.afinidade-com-animais','comum',1,'Afinidade com Animais','+2 de bônus nos testes de Adestrar Animais e Cavalgar',null,ARRAY[]::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"afinidade-com-animais","name":"Afinidade com Animais","section":"comum","prerequisites":"—","summary":"+2 de bônus nos testes de Adestrar Animais e Cavalgar","notes":[]}'::jsonb),
('dnd35.feat.agil','comum',1,'Ágil','+2 de bônus nos testes de Equilíbrio e Arte da Fuga',null,ARRAY[]::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"agil","name":"Ágil","section":"comum","prerequisites":"—","summary":"+2 de bônus nos testes de Equilíbrio e Arte da Fuga","notes":[]}'::jsonb),
('dnd35.feat.aptidao-magica','comum',1,'Aptidão Mágica','+2 de bônus nos testes de Identificar Magia e Usar Instrumento Mágico',null,ARRAY[]::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"aptidao-magica","name":"Aptidão Mágica","section":"comum","prerequisites":"—","summary":"+2 de bônus nos testes de Identificar Magia e Usar Instrumento Mágico","notes":[]}'::jsonb),
('dnd35.feat.ataque-desarmado-aprimorado','comum',1,'Ataque Desarmado Aprimorado','Considera-se que o personagem está armado quando desarmado — ou seja, oponentes armados não podem realizar ataques de oportunidade quando ele os ataca de mãos vazias. O personagem ainda pode desferir um ataque de oportunidade quando alguém desarmado tentar atacá-lo. Além disso, o personagem é capaz de causar dano letal ou dano por contusão usando seus ataques desarmados.',null,ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',92,'v35','dnd35','{"id":"ataque-desarmado-aprimorado","name":"Ataque Desarmado Aprimorado","section":"comum","prerequisites":"—","summary":"Considerado armado quando estiver desarmado","notes":[1],"full":{"id":"ataque-desarmado-aprimorado","name":"Ataque Desarmado Aprimorado","type":"geral","sourceBook":"D&D 3.5 — Livro do Jogador","sourcePage":92,"prerequisites":[],"benefit":"Considera-se que o personagem está armado quando desarmado — ou seja, oponentes armados não podem realizar ataques de oportunidade quando ele os ataca de mãos vazias. O personagem ainda pode desferir um ataque de oportunidade quando alguém desarmado tentar atacá-lo. Além disso, o personagem é capaz de causar dano letal ou dano por contusão usando seus ataques desarmados."}}'::jsonb),
('dnd35.feat.agarrar-aprimorado','comum',1,'Agarrar Aprimorado','Não provoca um ataque de oportunidade quando realiza o ataque de toque inicial da manobra Agarrar. Recebe +4 de bônus em todos os testes de Agarrar, não importa quem iniciou a manobra.','Des 13, Ataque Desarmado Aprimorado',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',89,'v35','dnd35','{"id":"agarrar-aprimorado","name":"Agarrar Aprimorado","section":"comum","prerequisites":"Des 13, Ataque Desarmado Aprimorado","summary":"+4 de bônus nos testes de Agarrar e não provoca ataques de oportunidade","notes":[1],"parent":"Ataque Desarmado Aprimorado","full":{"id":"agarrar-aprimorado","name":"Agarrar Aprimorado","type":"geral","sourceBook":"D&D 3.5 — Livro do Jogador","sourcePage":89,"prerequisites":["Des 13","Ataque Desarmado Aprimorado"],"benefit":"Não provoca um ataque de oportunidade quando realiza o ataque de toque inicial da manobra Agarrar. Recebe +4 de bônus em todos os testes de Agarrar, não importa quem iniciou a manobra."}}'::jsonb),
('dnd35.feat.desviar-objetos','comum',1,'Desviar Objetos','Desvia um ataque à distância por rodada','Des 13, Ataque Desarmado Aprimorado',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"desviar-objetos","name":"Desviar Objetos","section":"comum","prerequisites":"Des 13, Ataque Desarmado Aprimorado","summary":"Desvia um ataque à distância por rodada","notes":[1],"parent":"Ataque Desarmado Aprimorado"}'::jsonb),
('dnd35.feat.apanhar-objetos','comum',1,'Apanhar Objetos','Apanha uma arma arremessada ou projétil','Des 15, Desviar Objetos, Ataque Desarmado Aprimorado',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"apanhar-objetos","name":"Apanhar Objetos","section":"comum","prerequisites":"Des 15, Desviar Objetos, Ataque Desarmado Aprimorado","summary":"Apanha uma arma arremessada ou projétil","notes":[1],"parent":"Desviar Objetos"}'::jsonb),
('dnd35.feat.ataque-atordoante','comum',1,'Ataque Atordoante','O jogador precisa declarar que seu personagem está usando esse talento antes de realizar a jogada de ataque (logo, um fracasso na jogada desperdiçará a tentativa). Um oponente atingido por um ataque desarmado atordoante deve realizar um teste de resistência de Fortitude (CD 10 + metade do nível do atacante + modificador de Sab), além de sofrer o dano normalmente. Caso fracasse, o alvo ficará atordoado durante 1 rodada completa (até o final da próxima ação do personagem). Um personagem atordoado não consegue agir, perde qualquer bônus de Destreza na CA e sofre −2 de penalidade na CA. É possível desferir um ataque atordoante uma vez por dia a cada quatro níveis de personagem (veja Especial, a seguir), mas somente uma vez por rodada. Os constructos, limos, plantas, mortos-vivos, criaturas incorpóreas e criaturas imunes a sucessos decisivos não podem ser atordoadas. Especial: Um monge pode adquirir Ataque Atordoante como um talento adicional no 1º nível, mesmo quando não atender aos pré-requisitos. Quando adquire esse talento, ele conseguirá desferir uma quantidade de ataques atordoantes por dia equivalente ao seu nível de monge e uma vez adicional a cada quatro níveis de qualquer outra classe.','Des 13, Sab 13, Ataque Desarmado Aprimorado, bônus base de ataque +8',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',92,'v35','dnd35','{"id":"ataque-atordoante","name":"Ataque Atordoante","section":"comum","prerequisites":"Des 13, Sab 13, Ataque Desarmado Aprimorado, bônus base de ataque +8","summary":"Atordoa a vítima com um ataque desarmado","notes":[1],"parent":"Ataque Desarmado Aprimorado","full":{"id":"ataque-atordoante","name":"Ataque Atordoante","type":"geral","sourceBook":"D&D 3.5 — Livro do Jogador","sourcePage":92,"prerequisites":["Des 13","Sab 13","Ataque Desarmado Aprimorado","Bônus base de ataque +8"],"benefit":"O jogador precisa declarar que seu personagem está usando esse talento antes de realizar a jogada de ataque (logo, um fracasso na jogada desperdiçará a tentativa). Um oponente atingido por um ataque desarmado atordoante deve realizar um teste de resistência de Fortitude (CD 10 + metade do nível do atacante + modificador de Sab), além de sofrer o dano normalmente. Caso fracasse, o alvo ficará atordoado durante 1 rodada completa (até o final da próxima ação do personagem). Um personagem atordoado não consegue agir, perde qualquer bônus de Destreza na CA e sofre −2 de penalidade na CA. É possível desferir um ataque atordoante uma vez por dia a cada quatro níveis de personagem (veja Especial, a seguir), mas somente uma vez por rodada. Os constructos, limos, plantas, mortos-vivos, criaturas incorpóreas e criaturas imunes a sucessos decisivos não podem ser atordoadas. Especial: Um monge pode adquirir Ataque Atordoante como um talento adicional no 1º nível, mesmo quando não atender aos pré-requisitos. Quando adquire esse talento, ele conseguirá desferir uma quantidade de ataques atordoantes por dia equivalente ao seu nível de monge e uma vez adicional a cada quatro níveis de qualquer outra classe."}}'::jsonb),
('dnd35.feat.ataque-poderoso','comum',1,'Ataque Poderoso','Durante a ação de ataque do personagem, antes de realizar as jogadas de ataque, é possível subtrair um valor de todas as jogadas de ataque e aplicá-lo a todas as jogadas de dano. Esse valor não pode exceder seu bônus base de ataque. As alterações no ataque e no dano continuam válidas até seu próximo turno, inclusive para ataques de oportunidade.','For 13',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',92,'v35','dnd35','{"id":"ataque-poderoso","name":"Ataque Poderoso","section":"comum","prerequisites":"For 13","summary":"Substitui bônus de ataque por dano (máximo: bônus base de ataque)","notes":[1],"full":{"id":"ataque-poderoso","name":"Ataque Poderoso","type":"geral","sourceBook":"D&D 3.5 — Livro do Jogador","sourcePage":92,"prerequisites":["For 13"],"benefit":"Durante a ação de ataque do personagem, antes de realizar as jogadas de ataque, é possível subtrair um valor de todas as jogadas de ataque e aplicá-lo a todas as jogadas de dano. Esse valor não pode exceder seu bônus base de ataque. As alterações no ataque e no dano continuam válidas até seu próximo turno, inclusive para ataques de oportunidade."}}'::jsonb),
('dnd35.feat.trespassar','comum',1,'Trespassar','Desfere um ataque corporal extra depois de imobilizar um oponente','Ataque Poderoso',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"trespassar","name":"Trespassar","section":"comum","prerequisites":"Ataque Poderoso","summary":"Desfere um ataque corporal extra depois de imobilizar um oponente","notes":[1],"parent":"Ataque Poderoso"}'::jsonb),
('dnd35.feat.trespassar-maior','comum',1,'Trespassar Maior','Trespassar sem limite de ataques por rodada','Trespassar, Ataque Poderoso, bônus base de ataque +4',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"trespassar-maior","name":"Trespassar Maior","section":"comum","prerequisites":"Trespassar, Ataque Poderoso, bônus base de ataque +4","summary":"Trespassar sem limite de ataques por rodada","notes":[1],"parent":"Trespassar"}'::jsonb),
('dnd35.feat.encontrao-aprimorado','comum',1,'Encontrão Aprimorado','+4 de bônus nas tentativas de encontrão e não provoca ataques de oportunidade','Ataque Poderoso',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',90,'v35','dnd35','{"id":"encontrao-aprimorado","name":"Encontrão Aprimorado","section":"comum","prerequisites":"Ataque Poderoso","summary":"+4 de bônus nas tentativas de encontrão e não provoca ataques de oportunidade","notes":[1],"parent":"Ataque Poderoso"}'::jsonb),
