('dnd35.feat.combate-com-duas-armas','comum',1,'Combater com Duas Armas','As penalidades para combater com duas armas são reduzidas: a penalidade da mão principal diminui em 2 pontos e a da mão inábil diminui em 6 pontos.','Des 15',ARRAY['nota-1']::text[],'D&D 3.5 — Livro do Jogador',93,'v35','dnd35','{"id":"combate-com-duas-armas","name":"Combater com Duas Armas","section":"comum","prerequisites":"Des 15","summary":"Reduz −2 nas penalidades para combater com duas armas","notes":[1],"full":{"id":"combate-com-duas-armas","name":"Combate com Duas Armas","type":"geral","sourceBook":"D&D 3.5 — Livro do Jogador","sourcePage":93,"prerequisites":["Des 15"],"benefit":"As penalidades para combater com duas armas são reduzidas: a penalidade da mão principal diminui em 2 pontos e a da mão inábil diminui em 6 pontos."}}'::jsonb),
