('dnd35.feat.acelerar-magia','metamagico',1,'Acelerar Magia','O personagem pode conjurar magias com a velocidade do pensamento: uma magia acelerada usa a ação livre e ocupa o lugar de uma magia dois níveis superiores.',null,ARRAY[]::text[],'D&D 3.5 — Livro do Jogador',89,'v35','dnd35','{"id":"acelerar-magia","name":"Acelerar Magia","section":"metamagico","prerequisites":"—","summary":"Conjura a magia como ação livre","notes":[],"full":{"id":"acelerar-magia","name":"Acelerar Magia","type":"metamagico","sourceBook":"D&D 3.5 — Livro do Jogador","sourcePage":89,"prerequisites":[],"benefit":"O personagem pode conjurar magias com a velocidade do pensamento: uma magia acelerada usa a ação livre e ocupa o lugar de uma magia dois níveis superiores."}}'::jsonb),
